19	namespace att {
20	namespace {
21	constexpr size_t kMinNddmaRank = 1U;
22	constexpr size_t kMaxNddmaRank = 5U;
23	constexpr uint64_t kLowCoreUpperBound = 2U;
24	constexpr uint64_t kInputStrideUpperBound = 128U;
25	
26	// 合并模型直接表示最终多项式，避免运行时重新组合 NG、NGM 和 rho。
27	struct NddmaLowCoreParams {
28	  double constant;
29	  double bytes;
30	  double stride;
31	  double bytes_stride;
32	};
33	
34	struct NddmaHighCoreParams {
35	  double constant;
36	  double stride;
37	  double stride_square;
38	  double bytes;
39	  double bytes_stride;
40	  double bytes_stride_square;
41	};
42	
43	struct Nddma1DParams {
44	  NddmaLowCoreParams low_os_one;
45	  NddmaLowCoreParams low_os_ge_two;
46	  NddmaHighCoreParams high_os_one;
47	  NddmaHighCoreParams high_os_ge_two;
48	};
49	
50	const Nddma1DParams *GetNddma1DParams(uint64_t dtype_size) {
51	  static constexpr Nddma1DParams kB8 = {
52	      {194.421, 0.08501521772, 1.1117457, 0.0081160848},
53	      {53.81133, 6.998497418, 0.26072115, -0.0000079948},
54	      {373.274, 1.673508468, 0.008698207194, 0.1650886939, 0.01221712541, 0.00006349958196},
55	      {94.1599102, 0.5169452208, 0.000001100449223, 13.88854236, 0.00001331045708, -0.00000000003374437189}};
56	  static constexpr Nddma1DParams kB16 = {
57	      {204.604, 0.0388230407, 0.96094416, 0.0091341897},
58	      {61.53027, 3.498120341, 0.34357215, -0.0000114298},
59	      {399.909, 2.009597249, -0.007116959052, 0.07542046912, 0.01910209069, -0.00006764977277},
60	      {116.1609008, 0.6810487439, 0.0000008016156689, 6.936002307, -0.00001459675784, -0.00000000002666778076}};
61	  static constexpr Nddma1DParams kB32 = {
62	      {235.137, 0.01746346643, 0.3675047, 0.0058486918},
63	      {158.723147, 0.2427621164, 1.4596785, 0.0013874442},
64	      {453.859, 1.420515439, -0.008545279188, 0.03400250258, 0.02260694081, -0.0001359947351},
65	      {323.0812754, 0.7652737348, 0.03310192195, 0.4195876242, 0.007483747325, 0.00003146382551}};
66	  static constexpr Nddma1DParams kB64 = {
67	      {243.205, 0.01747194879, 0.90051511, 0.0030237371},
68	      {189.027128, 0.1244607288, 1.98330501, 0.0007092839},
69	      {468.971, 3.366949543, -0.02124182228, 0.03402448402, 0.0113054963, -0.00007132549515},
70	      {361.5012267, 4.200466405, -0.009748131943, 0.2462524565, 0.0008811088948, -0.000003486197538}};
71	  switch (dtype_size) {
72	    case 1U:
73	      return &kB8;
74	    case 2U:
75	      return &kB16;
76	    case 4U:
77	      return &kB32;
78	    case 8U:
79	      return &kB64;
80	    default:
81	      return nullptr;
82	  }
83	}
84	
85	bool HasValidVectorLengths(const NddmaDescriptorInfo &descriptor) {
86	  const size_t rank = descriptor.output_dims.size();
87	  return rank == descriptor.input_strides.size() && rank == descriptor.output_strides.size();
88	}
89	
90	bool HasValidAxisOrder(const NddmaDescriptorInfo &descriptor) {
91	  if (descriptor.vectorized_axis.size() != descriptor.output_dims.size()) {
92	    return false;
93	  }
94	  std::unordered_set<int64_t> unique_axes;
95	  for (const auto axis : descriptor.vectorized_axis) {
96	    if (!unique_axes.emplace(axis).second) {
97	      return false;
98	    }
99	  }
100	  return true;
101	}
102	
103	bool IsStaticNonPositive(const Expr &expr) {
104	  return expr.IsConstExpr() && af::SymbolicUtils::StaticCheckLe(expr, af::sym::kSymbolZero) == af::TriBool::kTrue;
105	}
106	
107	bool IsStaticNegative(const Expr &expr) {
108	  return expr.IsConstExpr() && af::SymbolicUtils::StaticCheckLt(expr, af::sym::kSymbolZero) == af::TriBool::kTrue;
109	}
110	
111	bool HasInvalidStaticValue(const NddmaNormalizedDesc &descriptor) {
112	  for (const auto &dim : descriptor.output_dims) {
113	    if (!IsValid(dim) || IsStaticNonPositive(dim)) {
114	      return true;
115	    }
116	  }
117	  for (const auto &stride : descriptor.input_strides) {
118	    if (!IsValid(stride) || IsStaticNegative(stride)) {
119	      return true;
120	    }
121	  }
122	  for (const auto &stride : descriptor.output_strides) {
123	    if (!IsValid(stride) || IsStaticNonPositive(stride)) {
124	      return true;
125	    }
126	  }
127	  return false;
128	}
129	
130	bool GetDtypeSize(const std::string &dtype, uint64_t &dtype_size) {
131	  const auto iter = kDataTypeSizeMap.find(dtype);
132	  return iter != kDataTypeSizeMap.end() && iter->second.GetConstValue(dtype_size);
133	}
134	
135	bool HasStaticByteCountOverflow(const Expr &dim, uint64_t dtype_size) {
136	  if (dtype_size == 0U) {
137	    return false;
138	  }
139	  int64_t dim_value = 0;
140	  if (!dim.IsConstExpr() || !dim.GetConstValue(dim_value) || dim_value <= 0) {
141	    return false;
142	  }
143	  return static_cast<uint64_t>(dim_value) > std::numeric_limits<uint64_t>::max() / dtype_size;
144	}
145	
146	Expr BuildLowCore(const NddmaLowCoreParams &params, const Expr &bytes, const Expr &stride) {
147	  return CreateExpr(params.constant) + CreateExpr(params.bytes) * bytes + CreateExpr(params.stride) * stride +
148	         CreateExpr(params.bytes_stride) * bytes * stride;
149	}
150	
151	Expr BuildHighCore(const NddmaHighCoreParams &params, const Expr &bytes, const Expr &stride) {
152	  const Expr stride_square = stride * stride;
153	  return CreateExpr(params.constant) + CreateExpr(params.stride) * stride +
154	         CreateExpr(params.stride_square) * stride_square +
155	         bytes * (CreateExpr(params.bytes) + CreateExpr(params.bytes_stride) * stride +
156	                  CreateExpr(params.bytes_stride_square) * stride_square);
157	}
158	
159	Expr SelectOutputStrideModel(const Expr &output_stride, const Expr &os_one, const Expr &os_ge_two) {
160	  if (output_stride.IsConstExpr()) {
161	    if (af::SymbolicUtils::StaticCheckEq(output_stride, af::sym::kSymbolOne) == af::TriBool::kTrue) {
162	      return os_one;
163	    }
164	    if (af::SymbolicUtils::StaticCheckGt(output_stride, af::sym::kSymbolOne) == af::TriBool::kTrue) {
165	      return os_ge_two;
166	    }
167	  }
168	  const Expr output_stride_gate =
169	      af::sym::Max(af::sym::kSymbolZero, af::sym::Min(af::sym::kSymbolOne, output_stride - af::sym::kSymbolOne));
170	  return os_one + output_stride_gate * (os_ge_two - os_one);
171	}
172	
173	void BuildNddma1DBranches(const NddmaNormalizedDesc &descriptor, uint64_t dtype_size, const Nddma1DParams &params,
174	                          Expr &low_core, Expr &high_core) {
175	  const Expr bytes = descriptor.output_dims[0] * CreateExpr(dtype_size);
176	  const Expr input_stride = af::sym::Min(CreateExpr(kInputStrideUpperBound), descriptor.input_strides[0]);
177	  const Expr low_os_one = BuildLowCore(params.low_os_one, bytes, input_stride);
178	  const Expr low_os_ge_two = BuildLowCore(params.low_os_ge_two, bytes, input_stride);
179	  const Expr high_os_one = BuildHighCore(params.high_os_one, bytes, input_stride);
180	  const Expr high_os_ge_two = BuildHighCore(params.high_os_ge_two, bytes, input_stride);
181	  low_core = SelectOutputStrideModel(descriptor.output_strides[0], low_os_one, low_os_ge_two);
182	  high_core = SelectOutputStrideModel(descriptor.output_strides[0], high_os_one, high_os_ge_two);
183	}
184	
185	af::Status SelectCoreBranch(const Expr &block_dim, const Expr &low_core, const Expr &high_core,
186	                            NddmaModelResult &result) {
187	  if (af::SymbolicUtils::StaticCheckLe(block_dim, CreateExpr(kLowCoreUpperBound)) == af::TriBool::kTrue) {
188	    result.cycles = low_core;
189	    return af::SUCCESS;
190	  }
191	  if (af::SymbolicUtils::StaticCheckGt(block_dim, CreateExpr(kLowCoreUpperBound)) == af::TriBool::kTrue) {
192	    result.cycles = high_core;
193	    return af::SUCCESS;
194	  }
195	  auto low_case = std::make_shared<IfCase>(low_core);
196	  auto high_case = std::make_shared<IfCase>(high_core);
197	  GE_ASSERT_NOTNULL(low_case);
198	  GE_ASSERT_NOTNULL(high_case);
199	  GetPerfVar("nddma_1d_multicore", result.cycles, result.ternary_ops);
200	  TernaryOp ternary(CondType::K_LE, block_dim, CreateExpr(kLowCoreUpperBound), std::move(low_case),
201	                    std::move(high_case));
202	  ternary.SetVariable(result.cycles);
203	  result.ternary_ops[result.cycles] = std::move(ternary);
204	  return af::SUCCESS;
205	}
206	}  // namespace
207	
208	const char *NddmaFallbackReasonToString(NddmaFallbackReason reason) {
209	  static constexpr const char *kReasons[] = {
210	      "none",           "no_descriptor",    "rank_unsupported",   "schema_mismatch", "dtype_unsupported",
211	      "stride_invalid", "codegen_mismatch", "no_registered_model"};
212	  const auto index = static_cast<size_t>(reason);
213	  return index < (sizeof(kReasons) / sizeof(kReasons[0])) ? kReasons[index] : "unknown";
214	}
215	
216	NddmaFallbackReason BuildNddmaDescriptor(const TensorShapeInfo &shape_info, const std::vector<int64_t> &vectorized_axis,
217	                                         NddmaDescriptorInfo &descriptor) {
218	  descriptor = NddmaDescriptorInfo{};
219	  if (shape_info.repeats.empty()) {
220	    return NddmaFallbackReason::kNoDescriptor;
221	  }
222	  if (shape_info.repeats.size() != shape_info.gm_strides.size() ||
223	      shape_info.repeats.size() != shape_info.strides.size()) {
224	    return NddmaFallbackReason::kSchemaMismatch;
225	  }
226	  descriptor.output_dims = shape_info.repeats;
227	  descriptor.input_strides = shape_info.gm_strides;
228	  descriptor.output_strides = shape_info.strides;
229	  if (vectorized_axis.empty()) {
230	    return NddmaFallbackReason::kCodegenMismatch;
231	  }
232	  descriptor.vectorized_axis = vectorized_axis;
233	  return NddmaFallbackReason::kNone;
234	}
235	
236	NddmaFallbackReason NormalizeNddmaDescriptor(const NddmaDescriptorInfo &descriptor, NddmaNormalizedDesc &normalized) {
237	  normalized = NddmaNormalizedDesc{};
238	  normalized.raw_rank = descriptor.output_dims.size();
239	  normalized.effective_rank = normalized.raw_rank;
240	  if (normalized.raw_rank < kMinNddmaRank || normalized.raw_rank > kMaxNddmaRank) {
241	    return NddmaFallbackReason::kRankUnsupported;
242	  }
243	  if (!HasValidVectorLengths(descriptor)) {
244	    return NddmaFallbackReason::kSchemaMismatch;
245	  }
246	  if (!HasValidAxisOrder(descriptor)) {
247	    return NddmaFallbackReason::kCodegenMismatch;
248	  }
249	  normalized.output_dims = descriptor.output_dims;
250	  normalized.input_strides = descriptor.input_strides;
251	  normalized.output_strides = descriptor.output_strides;
252	  normalized.vectorized_axis = descriptor.vectorized_axis;
253	  return HasInvalidStaticValue(normalized) ? NddmaFallbackReason::kStrideInvalid : NddmaFallbackReason::kNone;
254	}
255	
256	af::Status EvaluateNddmaModel(const NddmaDescriptorInfo &descriptor, const std::string &dtype, const Expr &block_dim,
257	                              NddmaModelResult &result) {
258	  result = NddmaModelResult{};
259	  NddmaNormalizedDesc normalized;
260	  result.fallback_reason = NormalizeNddmaDescriptor(descriptor, normalized);
261	  result.raw_rank = normalized.raw_rank;
262	  result.effective_rank = normalized.effective_rank;
263	  if (result.fallback_reason != NddmaFallbackReason::kNone) {
264	    return af::SUCCESS;
265	  }
266	  if (normalized.raw_rank != 1U || normalized.effective_rank != 1U) {
267	    result.fallback_reason = NddmaFallbackReason::kNoRegisteredModel;
268	    return af::SUCCESS;
269	  }
270	  uint64_t dtype_size = 0U;
271	  if (!GetDtypeSize(dtype, dtype_size)) {
272	    result.fallback_reason = NddmaFallbackReason::kDtypeUnsupported;
273	    return af::SUCCESS;
274	  }
275	  const auto *params = GetNddma1DParams(dtype_size);
276	  if (params == nullptr || IsStaticNonPositive(block_dim)) {
277	    result.fallback_reason =
278	        params == nullptr ? NddmaFallbackReason::kDtypeUnsupported : NddmaFallbackReason::kSchemaMismatch;
279	    return af::SUCCESS;
280	  }
281	  if (HasStaticByteCountOverflow(normalized.output_dims[0], dtype_size)) {
282	    result.fallback_reason = NddmaFallbackReason::kSchemaMismatch;
283	    return af::SUCCESS;
284	  }
285	  Expr low_core;
286	  Expr high_core;
287	  BuildNddma1DBranches(normalized, dtype_size, *params, low_core, high_core);
288	  GE_ASSERT_SUCCESS(SelectCoreBranch(block_dim, low_core, high_core, result));
289	  result.selected = true;
290	  result.fallback_reason = NddmaFallbackReason::kNone;
291	  return af::SUCCESS;
292	}
293	
294	void LogNddmaFallback(const std::string &node_name, const std::string &dtype, const NddmaDescriptorInfo *descriptor,
295	                      const NddmaModelResult &result) {
296	  GELOGW(
297	      "[ATT NDDMA] fallback: node=%s, raw_rank=%zu, effective_rank=%zu, dtype=%s, candidate_model=%s, "
298	      "fallback_reason=%s",
299	      node_name.c_str(), result.raw_rank, result.effective_rank, dtype.c_str(), result.model_name.c_str(),
300	      NddmaFallbackReasonToString(result.fallback_reason));
301	  if (descriptor != nullptr) {
302	    GELOGD("[ATT NDDMA] fallback detail: output_dims=[%s], input_strides=[%s], output_strides=[%s]",
303	           GetVecString(descriptor->output_dims).c_str(), GetVecString(descriptor->input_strides).c_str(),
304	           GetVecString(descriptor->output_strides).c_str());
305	  }
306	}
307	}  // namespace att
308

