30	af::Status TryNewNddmaModel(const TensorShapeInfo &shape_info, const NodeInfo &node, NodeDetail &node_detail,
31	                            PerfOutputInfo &perf_res, bool &selected) {
32	  selected = false;
33	  NddmaDescriptorInfo descriptor;
34	  NddmaModelResult result;
35	  // kUBFuse Codegen 分支生成 {curAivM, curAlignN} 和固定 2D stride，与下方 raw 描述不等价；
36	  // 在专用 2D 模型接入前保守回退 legacy ATT 模型。
37	  if (node.is_cv_ub_fusion) {
38	    result.raw_rank = shape_info.repeats.size();
39	    result.fallback_reason = NddmaFallbackReason::kCodegenMismatch;
40	    LogNddmaFallback(node_detail.name, shape_info.data_type, nullptr, result);
41	    return af::SUCCESS;
42	  }
43	  const auto build_reason = BuildNddmaDescriptor(shape_info, GetNddmaVectorizedAxis(node.node_ptr), descriptor);
44	  if (build_reason != NddmaFallbackReason::kNone) {
45	    result.raw_rank = shape_info.repeats.size();
46	    result.fallback_reason = build_reason;
47	    LogNddmaFallback(node_detail.name, shape_info.data_type, nullptr, result);
48	    return af::SUCCESS;
49	  }
50	  node_detail.nddma_descriptor = descriptor;
51	  GE_ASSERT_SUCCESS(EvaluateNddmaModel(descriptor, shape_info.data_type, CreateExpr("block_dim"), result));
52	  if (!result.selected) {
53	    LogNddmaFallback(node_detail.name, shape_info.data_type, &descriptor, result);
54	    return af::SUCCESS;
55	  }
56	  perf_res.pipe_res[PipeType::AIV_MTE2] = result.cycles;
57	  perf_res.ternary_ops.insert(result.ternary_ops.begin(), result.ternary_ops.end());
58	  selected = true;
59	  GELOGD("[ATT NDDMA] selected: node=%s, model=%s, raw_rank=%zu, effective_rank=%zu", node_detail.name.c_str(),
60	         result.model_name.c_str(), result.raw_rank, result.effective_rank);
61	  return af::SUCCESS;
62	}
