163	      MergeTensorContinuousDims(store_node_ptr, GetNodeOutTensorName(store_node_ptr, 0), merged_output_shapes));
164	  NodeDetail dma_info;
165	  dma_info.name = store_node_name;
166	  dma_info.optype = store_node_ptr->GetType();
167	  dma_info.input_dtype = {merged_output_shapes.data_type};
168	  dma_info.output_dtype = {merged_output_shapes.data_type};
169	  GE_ASSERT_SUCCESS(SetDims(merged_output_shapes, dma_info));
170	  GE_ASSERT_SUCCESS(GetDmaPerf(merged_output_shapes, dma_info, perf_res, kMaxDmaLen));
171	  return af::SUCCESS;
172	}
