174	inline af::Status CompareSpecificPerf(const std::string &mode, const NodeDetail &node_info, PerfOutputInfo &perf) {
175	  if (mode == kGe) {
176	    ascendcperf_v2::CompareGEPerf(node_info, perf);
177	  } else if (mode == kEq) {
178	    ascendcperf_v2::CompareEQPerf(node_info, perf);
179	  } else if (mode == kNe) {
180	    ascendcperf_v2::CompareNEPerf(node_info, perf);
181	  } else if (mode == kGt) {
182	    ascendcperf_v2::CompareGTPerf(node_info, perf);
183	  } else if (mode == kLe) {
184	    ascendcperf_v2::CompareLEPerf(node_info, perf);
185	  } else if (mode == kLt) {
186	    ascendcperf_v2::CompareLTPerf(node_info, perf);
187	  } else {
188	    GELOGW("compare mode %s is not registered", mode.c_str());
189	  }
190	  return af::SUCCESS;
191	}
