193	af::Status CompareApiV2([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
194	                        [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
195	                        [[maybe_unused]] const NodeInfo &node, const std::string &mode, PerfOutputInfo &perf_res) {
196	  GE_ASSERT_TRUE(input_shapes.size() >= 2U && !output_shapes.empty());
197	  NodeDetail node_info;
198	  Expr outer_repeat;
199	  vector<Expr> used_dims;
200	  GE_ASSERT_SUCCESS(GetOuterParams(output_shapes[0].dims, outer_repeat, used_dims));
201	  GE_ASSERT_SUCCESS(SetNodeDetail(input_shapes, output_shapes, node_info));
202	  GE_ASSERT_SUCCESS(SetDims(used_dims, node_info));
203	  node_info.compare_node_params = node.compare_node_params;
204	  GE_ASSERT_SUCCESS(CompareSpecificPerf(mode, node_info, perf_res));
205	  return af::SUCCESS;
206	}
