struct TensorShapeInfo {
  inline std::string GetDimExpr() const {
    std::stringstream ss;
    for (size_t i = 0U; i < dims.size(); i++) {
      if (i == (dims.size() - 1U)) {
        ss << dims[i];
      } else {
        ss << dims[i] << ",";
      }
    }
    return ss.str();
  }
